import hashlib,json,pathlib
base=pathlib.Path(__file__).resolve().parent; root=base.parents[1]
groups={
'src/xai_finance/reports/plots.py':[(1,13,'Path قياسية؛ matplotlib وNumPy وpandas وSHAP خارجية. يختار Agg قبل pyplot للعرض دون نافذة، ويحدد الألوان ونمط الرسوم العام.'),(16,21,'save_figure تضيف عنواناً للرسم الحالي وتضبط المساحة وتحفظ PNG وSVG ثم تغلق جميع الأشكال؛ تكتب ملفات وتعدل حالة matplotlib العامة.'),(24,36,'forecast_charts تنشئ مجلد الرسم ومحورين: القيم الفعلية بعد إزالة تواريخ مكررة وتوقع كل نموذج، ثم خطأ predicted−actual لكل نموذج. تضع الوحدات وتعرض الصفر وتحفظ؛ تفترض تطابق الفعلي بين النماذج وتسميات ألوان معروفة.'),(39,46,'metric_charts تحول قائمة المقاييس لجدول وترسم أعمدة MAE وRMSE وR² في محاور منفصلة وتحفظ، كي لا تخلط مقاييس ذات وحدات مختلفة في محور واحد.'),(49,57,'loss_chart ترسم خسارة تدريب وتحقق LSTM مقابل epoch بوحدات MSE للهدف المعياري؛ لا يعادل محورها RMSE بالدولار.'),(60,72,'research_flow تنشئ مجلدًا وشكلاً ثابت العقد والأسهم لوصف اللقطة والسمات والتقسيم والتدريب والاختبار والتفسير والمقاييس، وتضع تنبيه الإسكان وتحفظ. الرسم سردي وليس فحصاً آلياً للبيانات.'),(75,80,'explanation_charts تستقبل Explanation ومجلداً وسياقاً، وترسم beeswarm للمجموعة المحددة وwaterfall لأول تفسير وتحفظهما دون إظهار نافذة.'),(81,89,'تختار العمود ذي أكبر متوسط قيمة SHAP مطلقة ضمن المجموعة، وترسم الاعتماد على قيمته ثم تنشئ force plot لأول عينة وHTML، وتستدعي تجميع التأخيرات. المجموعة محدودة لا تمثل بالضرورة جميع الاختبار.'),(92,101,'aggregate_lag_charts تعيد تشكيل المساهمات إلى عينات×تأخيرات×سمات، وتجمع القيمة المطلقة عبر التأخيرات ثم تأخذ متوسط العينات وتصنف السمات وتكتب CSV ورسم أهم عشر. الجمع المطلق يفقد اتجاه التأثير ويمنع إلغاء الإشارات.'),(102,108,'ترسم خريطة قيم SHAP الموقعة لأول عينة، على محور السمات ومواضع النافذة، بمقياس متناظر حول الصفر وحد أدنى 1e-12؛ تحفظ الشكل. لا تستنتج سببية.')],
'scripts/start_scientific_validation.py':[(1,6,'يوثق تجميد البروتوكول، ويستورد الوقت والمسارات والبصمات والكتابة.'),(9,11,'protected_files تحصر ملفات الجذر باستثناء المسارات التي تحتوي أسماء المجلدات المستبعدة. القائمة الثابتة لا تضمن استبعاد كل بيئة أو ملف حساس في كل نشر؛ تتحقق من الأسماء ضمن مكونات المسار.'),(14,19,'main تحصر حجم وبصمة الملفات المحمية وتحدد مجلد تحقق جديداً باسم وقت UTC وتكتبه؛ exist_ok=False يمنع استعمال مجلد موجود.'),(20,37,'يبني قاموس البروتوكول الاستكشافي: الأصل المجمد والبذرة والأهداف والأصول ونوافذ 30×20 والنماذج والإعدادات والمراجع وثلاث طيات وحدود عدم اليقين والقيود. النفط مستبعد من العائد لا من فرق السعر لوجود سعر سالب؛ بيانات الاختبار الأصلية معروفة، فلا يمثل هذا اختباراً تأكيدياً مستقلاً.'),(38,44,'يكتب protocol.json ويطبع المسار والعدد وبصمة البروتوكول؛ حارس __main__ يستدعي التنفيذ المباشر. لم يشغل هذا السكربت في التوثيق.')],
'scripts/run_scientific_validation.py':[(1,8,'التوثيق يصف تحققاً إضافياً؛ argparse وPath قياسيتان، والبقية وظائف داخلية للقراءة والتدقيق وتشغيل وتجميع التجارب.'),(11,18,'main تحلل مجلد الوجهة والعمل audit أو train أو aggregate، ثم تقرأ البروتوكول وتحدد التشغيل الأصلي المشار إليه.'),(19,25,'audit يستدعي فحص الأصل؛ train يشغل التجارب ثم يجمعها؛ aggregate يجمع فقط. هذه الأوامر تحسب أو تدرب وتكتب في الوجهة؛ لم تشغل أثناء التوثيق.'),(28,29,'حارس التنفيذ المباشر يستدعي main.')],
'scripts/build_validation_report.py':[(1,7,'argparse وbase64 وhtml وPath قياسية، وread_json وwrite_report من المشروع.'),(10,18,'main تقرأ مجلد التحقق وتستدعي كتابة التقرير، ثم تجمع صور PNG وترمز بايتاتها base64 في figure وتقوم بتهريب العناوين. يستلزم write_report آثاراً سابقة ويولد تقارير ورسومات.'),(19,24,'تهرب نص Markdown وتدرجه كما هو داخل pre في صفحة HTML إنجليزية ذات صور مدمجة offline، وتكتب الصفحة ثم تؤكد خلو mismatches في verification.json وتطبع المسارات. فحص المحافظة يأتي بعد الكتابة وليس قبلها؛ الصفحة لا تحقق متطلبات التقرير العربي RTL.'),(27,28,'حارس التنفيذ يستدعي main.')],
'scripts/download_data.py':[(1,2,'يستورد load_config وdownload_all داخليتين.'),(4,4,'عند تنفيذ الملف أو استيراده يستدعي تنزيل الأصول وفق full_experiment.yaml؛ لقطة موجودة تمر بالتحقق كما في download_all. قد يحدث طلب شبكة وكتابة ولم ينفذ هنا.')]
}
manifest={}
for path,entries in groups.items():
 raw=(root/path).read_bytes(); src=raw.decode('utf8').splitlines(); name=path.replace('/','_')+'.md'; digest=hashlib.sha256(raw).hexdigest(); out=['# شرح `'+path+'`','',f'بصمة المصدر SHA-256: `{digest}`.','','الاقتباسات من الملف؛ لم تُشغّل السكربتات أو تجاربها.','']
 for start,end,desc in entries: out += [f'## الأسطر {start}–{end}','','```python',*src[start-1:end],'```','',desc,'']
 (base/'line_by_line'/name).write_text('\n'.join(out),encoding='utf8')
 manifest[path]={'document':'line_by_line/'+name,'ranges':[[a,b] for a,b,_ in entries],'sha256':digest,'review':'مراجعة يدوية غير مستقلة','quote_verification':'آلي'}
(base/'plots_orchestration_manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf8')
